INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6236,'comprehension','중심 내용 찾기 · 이 닦기의 중요성','이야기: 이를 닦지 않으면 충치가 생겨요. 충치가 생기면 이가 아프고 음식을 먹기 힘들어요. 그래서 밥을 먹고 꼭 이를 닦아야 해요.\n질문: 이 글에서 하고 싶은 말은 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,245,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6237,'comprehension','중심 내용 찾기 · 나무의 고마움','이야기: 나무는 맑은 공기를 만들어 줘요. 여름에는 시원한 그늘을 주고 새들의 집이 되어 줘요.\n질문: 이 글은 무엇을 말하고 있나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,246,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6238,'comprehension','중심 내용 찾기 · 가을 운동회','이야기: 가을 운동회 날 우리 반은 줄다리기와 이어달리기를 했어요. 모두 힘을 합쳐서 줄다리기에서 이겼어요.\n질문: 운동회에서 우리 반이 이긴 경기는 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,247,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6239,'comprehension','중심 내용 찾기 · 물 아끼기','이야기: 물은 우리 생활에 꼭 필요해요. 양치할 때 컵을 쓰고 샤워 시간을 줄이면 물을 아낄 수 있어요.\n질문: 물을 아끼는 방법 한 가지를 말해 보세요.\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,248,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6240,'comprehension','중심 내용 찾기 · 펭귄의 생활','이야기: 펭귄은 추운 남극에 살아요. 날지는 못하지만 헤엄을 아주 잘 쳐요. 물고기를 잡아먹으며 무리 지어 살아요.\n질문: 펭귄은 무엇을 잘하나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,249,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6241,'comprehension','중심 내용 찾기 · 교통 안전','이야기: 길을 건널 때는 신호등을 잘 봐야 해요. 초록불이 켜져도 좌우를 살피고 손을 들고 건너요.\n질문: 길을 건널 때 지켜야 할 것은 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,250,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6242,'comprehension','중심 내용 찾기 · 김치 만들기','이야기: 김치는 배추를 소금에 절인 뒤 양념을 버무려 만들어요. 우리 조상들은 겨울을 나려고 김장을 했어요.\n질문: 김치는 어떻게 만드나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,251,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6243,'comprehension','중심 내용 찾기 · 고마운 소방관','이야기: 소방관은 불을 끄고 위험에 빠진 사람을 구해요. 밤낮없이 우리를 지켜 주는 고마운 분들이에요.\n질문: 소방관은 어떤 일을 하나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,252,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6244,'comprehension','중심 내용 찾기 · 겨울잠','이야기: 곰과 개구리는 겨울이 오면 겨울잠을 자요. 먹이가 부족한 겨울을 잠을 자며 견뎌요.\n질문: 동물들이 겨울잠을 자는 까닭은 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,253,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6245,'comprehension','중심 내용 찾기 · 분리수거','이야기: 쓰레기를 종이, 플라스틱, 유리로 나누어 버리는 것을 분리수거라고 해요. 분리수거를 하면 다시 쓸 수 있는 물건이 많아져요.\n질문: 분리수거를 하면 무엇이 좋은가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,254,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6246,'comprehension','중심 내용 찾기 · 달의 모양','이야기: 달은 날마다 모양이 조금씩 바뀌어요. 가느다란 초승달이 점점 커져 둥근 보름달이 돼요.\n질문: 달은 어떻게 변하나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,255,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6247,'comprehension','중심 내용 찾기 · 골고루 먹기','이야기: 채소에는 비타민이, 고기에는 단백질이 많아요. 음식을 골고루 먹어야 몸이 튼튼해져요.\n질문: 이 글에서 하고 싶은 말은 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,256,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6248,'comprehension','중심 내용 찾기 · 한글의 탄생','이야기: 세종 대왕은 백성들이 글을 쉽게 읽고 쓰도록 한글을 만드셨어요. 한글은 배우기 쉬운 글자예요.\n질문: 세종 대왕은 왜 한글을 만드셨나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,257,1,'ADVANCED','LONG_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6249,'comprehension','중심 내용 찾기 · 개미의 협동','이야기: 개미는 큰 먹이를 혼자 옮기지 못해요. 그래서 여러 마리가 힘을 합쳐 먹이를 날라요.\n질문: 개미들은 큰 먹이를 어떻게 옮기나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,258,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6250,'comprehension','중심 내용 찾기 · 도서관 예절','이야기: 도서관에서는 조용히 해야 해요. 책은 깨끗하게 보고 다 읽은 책은 제자리에 꽂아요.\n질문: 도서관에서 지켜야 할 일 한 가지를 말해 보세요.\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,259,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6251,'comprehension','중심 내용 찾기 · 잠의 중요성','이야기: 잠을 푹 자면 몸이 쑥쑥 자라고 기억력도 좋아져요. 어린이는 하루에 아홉 시간 넘게 자는 것이 좋아요.\n질문: 잠을 푹 자면 무엇이 좋아지나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,260,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6252,'comprehension','중심 내용 찾기 · 사계절','이야기: 우리나라에는 봄, 여름, 가을, 겨울 네 계절이 있어요. 계절마다 날씨와 입는 옷이 달라요.\n질문: 우리나라에는 계절이 몇 개 있나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,261,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6253,'comprehension','중심 내용 찾기 · 손 씻기 습관','이야기: 손에는 눈에 보이지 않는 세균이 많아요. 밖에서 돌아오면 비누로 손을 깨끗이 씻어야 감기를 막을 수 있어요.\n질문: 손을 씻으면 무엇을 막을 수 있나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,262,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6254,'comprehension','중심 내용 찾기 · 씨앗 여행','이야기: 민들레 씨앗은 바람을 타고 멀리 날아가요. 도깨비바늘은 동물 털에 붙어서 다른 곳으로 가요.\n질문: 민들레 씨앗은 어떻게 멀리 가나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,263,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6255,'comprehension','중심 내용 찾기 · 화산','이야기: 화산은 땅속의 뜨거운 마그마가 밖으로 터져 나오는 산이에요. 뜨거운 용암이 흘러내려요.\n질문: 화산에서는 무엇이 흘러내리나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,264,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6256,'comprehension','중심 내용 찾기 · 설날 풍습','이야기: 설날에는 떡국을 먹고 웃어른께 세배를 드려요. 윷놀이와 연날리기도 해요.\n질문: 설날에 먹는 음식은 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,265,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6257,'comprehension','중심 내용 찾기 · 고래','이야기: 고래는 바다에 살지만 물고기가 아니에요. 새끼를 낳아 젖을 먹이고 숨을 쉬러 물 위로 올라와요.\n질문: 고래는 숨을 쉬려고 어떻게 하나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,266,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6258,'comprehension','중심 내용 찾기 · 친구와 사이좋게','이야기: 친구와 사이좋게 지내려면 서로 양보해야 해요. 친구 말을 잘 들어 주고 고마울 때 고맙다고 말해요.\n질문: 친구와 사이좋게 지내는 방법 한 가지는 무엇인가요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,267,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6259,'comprehension','중심 내용 찾기 · 비가 오는 까닭','이야기: 햇볕에 데워진 물은 수증기가 되어 하늘로 올라가요. 수증기가 모여 구름이 되고, 구름이 무거워지면 비가 내려요.\n질문: 구름이 무거워지면 어떻게 되나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,268,1,'ADVANCED','SHORT_SENTENCE',NULL);
INSERT IGNORE INTO `exercises` (`exercise_id`, `category_id`, `title`, `instruction`, `input_type`, `target_phonemes`, `sort_order`, `active`, `difficulty`, `content_type`, `pronunciation_rule`) VALUES (6260,'comprehension','중심 내용 찾기 · 우리 몸의 뼈','이야기: 우리 몸에는 이백 개가 넘는 뼈가 있어요. 뼈는 몸을 받쳐 주고 뇌와 심장 같은 기관을 보호해요.\n질문: 뼈는 어떤 일을 하나요?\n이야기를 읽고 질문에 알맞은 대답을 말해 보세요.','mic',NULL,269,1,'ADVANCED','SHORT_SENTENCE',NULL);
