INSERT IGNORE INTO `knowledge_documents` (`document_id`, `title`, `source_citation`, `source_url`, `publisher`, `author`, `published_year`, `topic`, `scope`, `license_note`, `review_status`, `version`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`, `category`, `source_version`, `verification_status`, `verified_at`, `verification_note`) VALUES ('std-pronunciation-1988','표준 발음법(표준어 규정 제2부)','문교부 고시 제88-2호(1988. 1. 19.) 「표준어 규정」 제2부 표준 발음법. 현행 원문은 국립국어원 한국어 어문 규범에서 확인.','https://korean.go.kr/kornorms/','국립국어원(현행 원문 제공)',NULL,1988,'표준 발음·음운 규칙','표준어를 말할 때의 표준 발음 규칙. 아동 조음 발달·조음 오류의 진단이나 치료 기준이 아니다.','정부 고시(어문 규범). 저작권법 제7조(보호받지 못하는 저작물)에 해당할 것으로 보이나 법적 검토 필요. 이 저장소의 청크는 원문이 아니라 개발자가 작성한 요약이다.','DRAFT',1,NULL,NULL,'2026-10-13 11:14:45','2026-10-13 11:14:45','PRONUNCIATION_RULE',NULL,'PENDING',NULL,NULL);
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-assimilation-17','nikl-pron-assimilation',17,'제5장 제17항','받침 ‘ㄷ, ㅌ(ㄾ)’이 조사나 접미사의 모음 ‘ㅣ’와 결합되는 경우에는, [ㅈ, ㅊ]으로 바꾸어서 뒤 음절 첫소리로 옮겨 발음한다. 곧이듣다[고지듣따], 굳이[구지], 미닫이[미ː다지], 땀받이[땀바지], 밭이[바치], 벼훑이[벼훌치] [붙임] ‘ㄷ’ 뒤에 접미사 ‘히’가 결합되어 ‘티’를 이루는 것은 [치]로 발음한다. 굳히다[구치다], 닫히다[다치다], 묻히다[무치다]','rule:17,slot:CODA,phoneme:ㄷ,phoneme:ㅌ,phoneme:ㄾ,phoneme:ㅣ,phoneme:ㅈ,phoneme:ㅊ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-assimilation-18','nikl-pron-assimilation',18,'제5장 제18항','받침 ‘ㄱ(ㄲ, ㅋ, ㄳ, ㄺ), ㄷ(ㅅ, ㅆ, ㅈ, ㅊ, ㅌ, ㅎ), ㅂ(ㅍ, ㄼ, ㄿ, ㅄ)’은 ‘ㄴ, ㅁ’ 앞에서 [ㅇ, ㄴ, ㅁ]으로 발음한다. 먹는[멍는], 국물[궁물], 깎는[깡는], 키읔만[키응만], 몫몫이[몽목씨], 긁는[긍는], 흙만[흥만], 닫는[단는], 짓는[진ː는], 옷맵시[온맵씨], 있는[인는], 맞는[만는], 젖멍울[전멍울], 쫓는[쫀는], 꽃망울[꼰망울], 붙는[분는], 놓는[논는], 잡는[잠는], 밥물[밤물], 앞마당[암마당], 밟는[밤ː는], 읊는[음는], 없는[엄ː는] [붙임] 두 단어를 이어서 한 마디로 발음하는 경우에도 이와 같다. 책 넣는다[챙넌는다], 흙 말리다[흥말리다], 옷 맞추다[온맏추다], 밥 먹는다[밤멍는다], 값 매기다[감매기다]','rule:18,slot:CODA,phoneme:ㄱ,phoneme:ㄲ,phoneme:ㅋ,phoneme:ㄳ,phoneme:ㄺ,phoneme:ㄷ,phoneme:ㅅ,phoneme:ㅆ,phoneme:ㅈ,phoneme:ㅊ,phoneme:ㅌ,phoneme:ㅎ,phoneme:ㅂ,phoneme:ㅍ,phoneme:ㄼ,phoneme:ㄿ,phoneme:ㅄ,phoneme:ㄴ,phoneme:ㅁ,phoneme:ㅇ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-assimilation-19','nikl-pron-assimilation',19,'제5장 제19항','받침 ‘ㅁ, ㅇ’ 뒤에 연결되는 ‘ㄹ’은 [ㄴ]으로 발음한다. 담력[담ː녁], 침략[침ː냑], 강릉[강능], 항로[항ː노], 대통령[대ː통녕] [붙임] 받침 ‘ㄱ, ㅂ’ 뒤에 연결되는 ‘ㄹ’도 [ㄴ]으로 발음한다. 막론[막논→망논], 석류[석뉴→성뉴], 협력[협녁→혐녁], 법리[법니→범니]','rule:19,slot:ONSET,phoneme:ㅁ,phoneme:ㅇ,phoneme:ㄹ,phoneme:ㄴ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-assimilation-20','nikl-pron-assimilation',20,'제5장 제20항','‘ㄴ’은 ‘ㄹ’의 앞이나 뒤에서 [ㄹ]로 발음한다. (1) 난로[날ː로], 신라[실라], 천리[철리], 광한루[광ː할루], 대관령[대ː괄령] (2) 칼날[칼랄], 물난리[물랄리], 줄넘기[줄럼끼], 할는지[할른지] [붙임] 첫소리 ‘ㄴ’이 ‘ㅀ’, ‘ㄾ’ 뒤에 연결되는 경우에도 이에 준한다. 닳는[달른], 뚫는[뚤른], 핥네[할레] 다만, 다음과 같은 단어들은 ‘ㄹ’을 [ㄴ]으로 발음한다. 의견란[의ː견난], 임진란[임ː진난], 생산량[생산냥], 결단력[결딴녁], 공권력[공꿘녁], 동원령[동ː원녕], 상견례[상견녜], 횡단로[횡단노], 이원론[이ː원논], 입원료[이붠뇨], 구근류[구근뉴]','rule:20,slot:CODA,slot:ONSET,phoneme:ㄴ,phoneme:ㄹ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-assimilation-23','nikl-pron-assimilation',23,'제6장 제23항','받침 ‘ㄱ(ㄲ, ㅋ, ㄳ, ㄺ), ㄷ(ㅅ, ㅆ, ㅈ, ㅊ, ㅌ), ㅂ(ㅍ, ㄼ, ㄿ, ㅄ)’ 뒤에 연결되는 ‘ㄱ, ㄷ, ㅂ, ㅅ, ㅈ’은 된소리로 발음한다. 국밥[국빱], 깎다[깍따], 넋받이[넉빠지], 삯돈[삭똔], 닭장[닥짱], 칡범[칙뻠], 뻗대다[뻗때다], 옷고름[옫꼬름], 있던[읻떤], 꽂고[꼳꼬], 꽃다발[꼳따발], 낯설다[낟썰다], 밭갈이[받까리], 솥전[솓쩐], 곱돌[곱똘], 덮개[덥깨], 옆집[엽찝], 넓죽하다[넙쭈카다], 읊조리다[읍쪼리다], 값지다[갑찌다]','rule:23,slot:ONSET,phoneme:ㄱ,phoneme:ㄲ,phoneme:ㅋ,phoneme:ㄳ,phoneme:ㄺ,phoneme:ㄷ,phoneme:ㅅ,phoneme:ㅆ,phoneme:ㅈ,phoneme:ㅊ,phoneme:ㅌ,phoneme:ㅂ,phoneme:ㅍ,phoneme:ㄼ,phoneme:ㄿ,phoneme:ㅄ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-08','nikl-pron-coda',8,'제4장 제8항','받침소리로는 ‘ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅇ’의 7개 자음만 발음한다.','rule:8,slot:CODA,phoneme:ㄱ,phoneme:ㄴ,phoneme:ㄷ,phoneme:ㄹ,phoneme:ㅁ,phoneme:ㅂ,phoneme:ㅇ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-09','nikl-pron-coda',9,'제4장 제9항','받침 ‘ㄲ, ㅋ’, ‘ㅅ, ㅆ, ㅈ, ㅊ, ㅌ’, ‘ㅍ’은 어말 또는 자음 앞에서 각각 대표음 [ㄱ, ㄷ, ㅂ]으로 발음한다. 닦다[닥따], 키읔[키윽], 키읔과[키윽꽈], 옷[옫], 웃다[욷ː따], 있다[읻따], 젖[젇], 빚다[빋따], 꽃[꼳], 쫓다[쫃따], 솥[솓], 뱉다[밷ː따], 앞[압], 덮다[덥따]','rule:9,slot:CODA,phoneme:ㄲ,phoneme:ㅋ,phoneme:ㅅ,phoneme:ㅆ,phoneme:ㅈ,phoneme:ㅊ,phoneme:ㅌ,phoneme:ㅍ,phoneme:ㄱ,phoneme:ㄷ,phoneme:ㅂ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-10','nikl-pron-coda',10,'제4장 제10항','겹받침 ‘ㄳ’, ‘ㄵ’, ‘ㄼ, ㄽ, ㄾ’, ‘ㅄ’은 어말 또는 자음 앞에서 각각 [ㄱ, ㄴ, ㄹ, ㅂ]으로 발음한다. 넋[넉], 넋과[넉꽈], 앉다[안따], 여덟[여덜], 넓다[널따], 외곬[외골], 핥다[할따], 값[갑], 없다[업ː따] 다만, ‘밟-’은 자음 앞에서 [밥]으로 발음하고, ‘넓-’은 다음과 같은 경우에 [넙]으로 발음한다. (1) 밟다[밥ː따], 밟소[밥ː쏘], 밟지[밥ː찌], 밟는[밥ː는→밤ː는], 밟게[밥ː께], 밟고[밥ː꼬] (2) 넓-죽하다[넙쭈카다], 넓-둥글다[넙뚱글다]','slot:CODA,phoneme:ㄳ,phoneme:ㄵ,phoneme:ㄼ,phoneme:ㄽ,phoneme:ㄾ,phoneme:ㅄ,phoneme:ㄱ,phoneme:ㄴ,phoneme:ㄹ,phoneme:ㅂ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-11','nikl-pron-coda',11,'제4장 제11항','겹받침 ‘ㄺ, ㄻ, ㄿ’은 어말 또는 자음 앞에서 각각 [ㄱ, ㅁ, ㅂ]으로 발음한다. 닭[닥], 흙과[흑꽈], 맑다[막따], 늙지[늑찌], 삶[삼ː], 젊다[점ː따], 읊고[읍꼬], 읊다[읍따] 다만, 용언의 어간 말음 ‘ㄺ’은 ‘ㄱ’ 앞에서 [ㄹ]로 발음한다. 맑게[말께], 묽고[물꼬], 얽거나[얼꺼나]','slot:CODA,phoneme:ㄺ,phoneme:ㄻ,phoneme:ㄿ,phoneme:ㄱ,phoneme:ㅁ,phoneme:ㅂ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-12','nikl-pron-coda',12,'제4장 제12항','받침 ‘ㅎ’의 발음은 다음과 같다. 1. ‘ㅎ(ㄶ, ㅀ)’ 뒤에 ‘ㄱ, ㄷ, ㅈ’이 결합되는 경우에는, 뒤 음절 첫소리와 합쳐서 [ㅋ, ㅌ, ㅊ]으로 발음한다. 놓고[노코], 좋던[조ː턴], 쌓지[싸치], 많고[만ː코], 않던[안턴], 닳지[달치] [붙임 1] 받침 ‘ㄱ(ㄺ), ㄷ, ㅂ(ㄼ), ㅈ(ㄵ)’이 뒤 음절 첫소리 ‘ㅎ’과 결합되는 경우에도, 역시 두 음을 합쳐서 [ㅋ, ㅌ, ㅍ, ㅊ]으로 발음한다. 각하[가카], 먹히다[머키다], 밝히다[발키다], 맏형[마텽], 좁히다[조피다], 넓히다[널피다], 꽂히다[꼬치다], 앉히다[안치다] [붙임 2] 규정에 따라 \'ㄷ\'으로 발음되는 ‘ㅅ, ㅈ, ㅊ, ㅌ’의 경우에도 이에 준한다. 옷 한 벌[오탄벌], 낮 한때[나탄때], 꽃 한 송이[꼬탄송이], 숱하다[수타다] 2. ‘ㅎ(ㄶ, ㅀ)’ 뒤에 ‘ㅅ’이 결합되는 경우에는, ‘ㅅ’을 [ㅆ]으로 발음한다. 닿소[다ː쏘], 많소[만ː쏘], 싫소[실쏘] 3. ‘ㅎ’ 뒤에 ‘ㄴ’이 결합되는 경우에는, [ㄴ]으로 발음한다. 놓는[논는], 쌓네[싼네] [붙임] ‘ㄶ, ㅀ’ 뒤에 ‘ㄴ’이 결합되는 경우에는, ‘ㅎ’을 발음하지 않는다. 않네[안네], 않는[안는], 뚫네[뚤네→뚤레], 뚫는[뚤는→뚤른] * ‘뚫네[뚤네→뚤레], 뚫는[뚤는→뚤른]’에 대해서는 제20항 참조. 4. ‘ㅎ(ㄶ, ㅀ)’ 뒤에 모음으로 시작된 어미나 접미사가 결합되는 경우에는, ‘ㅎ’을 발음하지 않는다. 낳은[나은], 놓아[노아], 쌓이다[싸이다], 많아[마ː나], 않은[아는], 닳아[다라], 싫어도[시러도]','slot:CODA,phoneme:ㅎ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-13','nikl-pron-coda',13,'제4장 제13항','홑받침이나 쌍받침이 모음으로 시작된 조사나 어미, 접미사와 결합되는 경우에는, 제 음가대로 뒤 음절 첫소리로 옮겨 발음한다. 깎아[까까], 옷이[오시], 있어[이써], 낮이[나지], 꽂아[꼬자], 꽃을[꼬츨], 쫓아[쪼차], 밭에[바테], 앞으로[아프로], 덮이다[더피다]','rule:13,slot:CODA,slot:ONSET');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-14','nikl-pron-coda',14,'제4장 제14항','겹받침이 모음으로 시작된 조사나 어미, 접미사와 결합되는 경우에는, 뒤엣것만을 뒤 음절 첫소리로 옮겨 발음한다.(이 경우, ‘ㅅ’은 된소리로 발음함.) 넋이[넉씨], 앉아[안자], 닭을[달글], 젊어[절머], 곬이[골씨], 핥아[할타], 읊어[을퍼], 값을[갑쓸], 없어[업ː써]','slot:CODA,phoneme:ㅅ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-15','nikl-pron-coda',15,'제4장 제15항','받침 뒤에 모음 ‘ㅏ, ㅓ, ㅗ, ㅜ, ㅟ’ 들로 시작되는 실질 형태소가 연결되는 경우에는, 대표음으로 바꾸어서 뒤 음절 첫소리로 옮겨 발음한다. 밭 아래[바다래], 늪 앞[느밥], 젖어미[저더미], 맛없다[마덥따], 겉옷[거돋], 헛웃음[허두슴], 꽃 위[꼬뒤] 다만, ‘맛있다, 멋있다’는 [마싣따], [머싣따]로도 발음할 수 있다. [붙임] 겹받침의 경우에는, 그중 하나만을 옮겨 발음한다. 넋 없다[너겁따], 닭 앞에[다가페], 값어치[가버치], 값있는[가빈는]','slot:CODA,phoneme:ㅏ,phoneme:ㅓ,phoneme:ㅗ,phoneme:ㅜ,phoneme:ㅟ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-coda-16','nikl-pron-coda',16,'제4장 제16항','한글 자모의 이름은 그 받침소리를 연음하되, ‘ㄷ, ㅈ, ㅊ, ㅋ, ㅌ, ㅍ, ㅎ’의 경우에는 특별히 다음과 같이 발음한다. 디귿이[디그시], 디귿을[디그슬], 디귿에[디그세], 지읒이[지으시], 지읒을[지으슬], 지읒에[지으세], 치읓이[치으시], 치읓을[치으슬], 치읓에[치으세], 키읔이[키으기], 키읔을[키으글], 키읔에[키으게], 티읕이[티으시], 티읕을[티으슬], 티읕에[티으세], 피읖이[피으비], 피읖을[피으블], 피읖에[피으베], 히읗이[히으시], 히읗을[히으슬], 히읗에[히으세]','slot:CODA,phoneme:ㄷ,phoneme:ㅈ,phoneme:ㅊ,phoneme:ㅋ,phoneme:ㅌ,phoneme:ㅍ,phoneme:ㅎ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-consonant-02','nikl-pron-consonant',2,'제2장 제2항','표준어의 자음은 다음 19개로 한다. ㄱ, ㄲ, ㄴ, ㄷ, ㄸ, ㄹ, ㅁ, ㅂ, ㅃ, ㅅ, ㅆ, ㅇ, ㅈ, ㅉ, ㅊ, ㅋ, ㅌ, ㅍ, ㅎ','slot:ONSET,phoneme:ㄱ,phoneme:ㄲ,phoneme:ㄴ,phoneme:ㄷ,phoneme:ㄸ,phoneme:ㄹ,phoneme:ㅁ,phoneme:ㅂ,phoneme:ㅃ,phoneme:ㅅ,phoneme:ㅆ,phoneme:ㅇ,phoneme:ㅈ,phoneme:ㅉ,phoneme:ㅊ,phoneme:ㅋ,phoneme:ㅌ,phoneme:ㅍ,phoneme:ㅎ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-01','nikl-pron-manner',1,'제2장 제2항 해설(자음 분류표)','국어의 자음은 소리 나는 방식에 따라서 다양하게 분류할 수 있다. 공기를 막았다가 터뜨리는 파열음, 좁은 틈으로 공기를 마찰하여 내는 마찰음, 공기를 막았다가 마찰하여 내는 파찰음, 코로 공기를 보내어 내는 비음, 공기의 흐름을 거의 방해하지 않으며 내는 유음의 다섯 가지로 구분된다. 파열음, 마찰음, 파찰음은 다시 평음(예사소리), 경음(된소리), 격음(거센소리)의 세 부류로 구분된다. 이러한 자음의 구분 방식은 국어의 특징 중 하나이다. [분류표] 파열음: ㅂ(양순음, 평음), ㄷ(치조음, 평음), ㄱ(연구개음, 평음), ㅃ(양순음, 경음), ㄸ(치조음, 경음), ㄲ(연구개음, 경음), ㅍ(양순음, 격음), ㅌ(치조음, 격음), ㅋ(연구개음, 격음)','phoneme:ㅂ,phoneme:ㄷ,phoneme:ㄱ,phoneme:ㅃ,phoneme:ㄸ,phoneme:ㄲ,phoneme:ㅍ,phoneme:ㅌ,phoneme:ㅋ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-02','nikl-pron-manner',2,'제2장 제2항 해설(자음 분류표)','국어의 자음은 소리 나는 방식에 따라서 다양하게 분류할 수 있다. 공기를 막았다가 터뜨리는 파열음, 좁은 틈으로 공기를 마찰하여 내는 마찰음, 공기를 막았다가 마찰하여 내는 파찰음, 코로 공기를 보내어 내는 비음, 공기의 흐름을 거의 방해하지 않으며 내는 유음의 다섯 가지로 구분된다. 파열음, 마찰음, 파찰음은 다시 평음(예사소리), 경음(된소리), 격음(거센소리)의 세 부류로 구분된다. 이러한 자음의 구분 방식은 국어의 특징 중 하나이다. [분류표] 마찰음: ㅅ(치조음, 평음), ㅎ(후음), ㅆ(치조음, 경음)','phoneme:ㅅ,phoneme:ㅎ,phoneme:ㅆ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-03','nikl-pron-manner',3,'제2장 제2항 해설(자음 분류표)','국어의 자음은 소리 나는 방식에 따라서 다양하게 분류할 수 있다. 공기를 막았다가 터뜨리는 파열음, 좁은 틈으로 공기를 마찰하여 내는 마찰음, 공기를 막았다가 마찰하여 내는 파찰음, 코로 공기를 보내어 내는 비음, 공기의 흐름을 거의 방해하지 않으며 내는 유음의 다섯 가지로 구분된다. 파열음, 마찰음, 파찰음은 다시 평음(예사소리), 경음(된소리), 격음(거센소리)의 세 부류로 구분된다. 이러한 자음의 구분 방식은 국어의 특징 중 하나이다. [분류표] 파찰음: ㅈ(경구개음, 평음), ㅉ(경구개음, 경음), ㅊ(경구개음, 격음)','phoneme:ㅈ,phoneme:ㅉ,phoneme:ㅊ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-04','nikl-pron-manner',4,'제2장 제2항 해설(자음 분류표)','국어의 자음은 소리 나는 방식에 따라서 다양하게 분류할 수 있다. 공기를 막았다가 터뜨리는 파열음, 좁은 틈으로 공기를 마찰하여 내는 마찰음, 공기를 막았다가 마찰하여 내는 파찰음, 코로 공기를 보내어 내는 비음, 공기의 흐름을 거의 방해하지 않으며 내는 유음의 다섯 가지로 구분된다. 파열음, 마찰음, 파찰음은 다시 평음(예사소리), 경음(된소리), 격음(거센소리)의 세 부류로 구분된다. 이러한 자음의 구분 방식은 국어의 특징 중 하나이다. [분류표] 비음: ㅁ(양순음), ㄴ(치조음), ㅇ(연구개음)','phoneme:ㅁ,phoneme:ㄴ,phoneme:ㅇ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-05','nikl-pron-manner',5,'제2장 제2항 해설(자음 분류표)','국어의 자음은 소리 나는 방식에 따라서 다양하게 분류할 수 있다. 공기를 막았다가 터뜨리는 파열음, 좁은 틈으로 공기를 마찰하여 내는 마찰음, 공기를 막았다가 마찰하여 내는 파찰음, 코로 공기를 보내어 내는 비음, 공기의 흐름을 거의 방해하지 않으며 내는 유음의 다섯 가지로 구분된다. 파열음, 마찰음, 파찰음은 다시 평음(예사소리), 경음(된소리), 격음(거센소리)의 세 부류로 구분된다. 이러한 자음의 구분 방식은 국어의 특징 중 하나이다. [분류표] 유음: ㄹ(치조음)','phoneme:ㄹ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-manner-06','nikl-pron-manner',6,'제2장 제2항 해설','후음인 ‘ㅎ’은 격음이나 평음 등으로 분류하지 않고 제시하였다. 평음, 경음, 격음으로 구분하는 것은 파열음처럼 3항 대립이 있을 때 의미가 있는데, 후음은 ‘ㅎ’ 하나로, 대립하는 다른 자음이 없다. 따라서 비음이나 유음과 마찬가지로 구분하지 않고 제시하였다.','phoneme:ㅎ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-place-01','nikl-pron-place',1,'제2장 제2항 해설(자음 분류표)','국어의 자음은 5개의 조음 위치에서 발음된다. 두 입술에서 내는 양순음, 혀끝을 치조 부위에 대거나 접근하여 내는 치조음, 혀의 앞부분을 경구개 부위에 대어 내는 경구개음, 혀의 뒷부분을 연구개 부위에 대어 내는 연구개음, 성문에서 내는 후음이 있다. [분류표] 양순음: ㅂ(파열음 평음), ㅃ(파열음 경음), ㅍ(파열음 격음), ㅁ(비음)','phoneme:ㅂ,phoneme:ㅃ,phoneme:ㅍ,phoneme:ㅁ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-place-02','nikl-pron-place',2,'제2장 제2항 해설(자음 분류표)','국어의 자음은 5개의 조음 위치에서 발음된다. 두 입술에서 내는 양순음, 혀끝을 치조 부위에 대거나 접근하여 내는 치조음, 혀의 앞부분을 경구개 부위에 대어 내는 경구개음, 혀의 뒷부분을 연구개 부위에 대어 내는 연구개음, 성문에서 내는 후음이 있다. [분류표] 치조음: ㄷ(파열음 평음), ㄸ(파열음 경음), ㅌ(파열음 격음), ㅅ(마찰음 평음), ㅆ(마찰음 경음), ㄴ(비음), ㄹ(유음)','phoneme:ㄷ,phoneme:ㄸ,phoneme:ㅌ,phoneme:ㅅ,phoneme:ㅆ,phoneme:ㄴ,phoneme:ㄹ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-place-03','nikl-pron-place',3,'제2장 제2항 해설(자음 분류표)','국어의 자음은 5개의 조음 위치에서 발음된다. 두 입술에서 내는 양순음, 혀끝을 치조 부위에 대거나 접근하여 내는 치조음, 혀의 앞부분을 경구개 부위에 대어 내는 경구개음, 혀의 뒷부분을 연구개 부위에 대어 내는 연구개음, 성문에서 내는 후음이 있다. [분류표] 경구개음: ㅈ(파찰음 평음), ㅉ(파찰음 경음), ㅊ(파찰음 격음)','phoneme:ㅈ,phoneme:ㅉ,phoneme:ㅊ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-place-04','nikl-pron-place',4,'제2장 제2항 해설(자음 분류표)','국어의 자음은 5개의 조음 위치에서 발음된다. 두 입술에서 내는 양순음, 혀끝을 치조 부위에 대거나 접근하여 내는 치조음, 혀의 앞부분을 경구개 부위에 대어 내는 경구개음, 혀의 뒷부분을 연구개 부위에 대어 내는 연구개음, 성문에서 내는 후음이 있다. [분류표] 연구개음: ㄱ(파열음 평음), ㄲ(파열음 경음), ㅋ(파열음 격음), ㅇ(비음)','phoneme:ㄱ,phoneme:ㄲ,phoneme:ㅋ,phoneme:ㅇ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-place-05','nikl-pron-place',5,'제2장 제2항 해설(자음 분류표)','국어의 자음은 5개의 조음 위치에서 발음된다. 두 입술에서 내는 양순음, 혀끝을 치조 부위에 대거나 접근하여 내는 치조음, 혀의 앞부분을 경구개 부위에 대어 내는 경구개음, 혀의 뒷부분을 연구개 부위에 대어 내는 연구개음, 성문에서 내는 후음이 있다. [분류표] 후음: ㅎ(마찰음)','phoneme:ㅎ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-vowel-03','nikl-pron-vowel',3,'제2장 제3항','표준어의 모음은 다음 21개로 한다. ㅏ, ㅐ, ㅑ, ㅒ, ㅓ, ㅔ, ㅕ, ㅖ, ㅗ, ㅘ, ㅙ, ㅚ, ㅛ, ㅜ, ㅝ, ㅞ, ㅟ, ㅠ, ㅡ, ㅢ, ㅣ','slot:NUCLEUS,phoneme:ㅏ,phoneme:ㅐ,phoneme:ㅑ,phoneme:ㅒ,phoneme:ㅓ,phoneme:ㅔ,phoneme:ㅕ,phoneme:ㅖ,phoneme:ㅗ,phoneme:ㅘ,phoneme:ㅙ,phoneme:ㅚ,phoneme:ㅛ,phoneme:ㅜ,phoneme:ㅝ,phoneme:ㅞ,phoneme:ㅟ,phoneme:ㅠ,phoneme:ㅡ,phoneme:ㅢ,phoneme:ㅣ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-vowel-04','nikl-pron-vowel',4,'제2장 제4항','‘ㅏ ㅐ ㅓ ㅔ ㅗ ㅚ ㅜ ㅟ ㅡ ㅣ’는 단모음(單母音)으로 발음한다. [붙임] ‘ㅚ, ㅟ’는 이중 모음으로 발음할 수 있다.','slot:NUCLEUS,phoneme:ㅏ,phoneme:ㅐ,phoneme:ㅓ,phoneme:ㅔ,phoneme:ㅗ,phoneme:ㅚ,phoneme:ㅜ,phoneme:ㅟ,phoneme:ㅡ,phoneme:ㅣ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-vowel-05','nikl-pron-vowel',5,'제2장 제5항','‘ㅑ ㅒ ㅕ ㅖ ㅘ ㅙ ㅛ ㅝ ㅞ ㅠ ㅢ’는 이중 모음으로 발음한다. 다만 1. 용언의 활용형에 나타나는 ‘져, 쪄, 쳐’는 [저, 쩌, 처]로 발음한다. 가지어→가져[가저], 찌어→쪄[쩌], 다치어→다쳐[다처] 다만 2. ‘예, 례\' 이외의 ‘ㅖ’는 [ㅔ]로도 발음한다. 계집[계ː집/게ː집], 계시다[계ː시다/게ː시다], 시계[시계/시게](時計), 연계[연계/연게](連繫), 몌별[몌별/메별](袂別), 개폐[개폐/개페](開閉), 혜택[혜ː택/헤ː택](惠澤), 지혜[지혜/지헤](智慧) 다만 3. 자음을 첫소리로 가지고 있는 음절의 ‘ㅢ’는 [ㅣ]로 발음한다. 늴리리, 닁큼, 무늬, 띄어쓰기, 씌어, 틔어, 희어, 희떱다, 희망, 유희 다만 4. 단어의 첫음절 이외의 ‘의’는 [ㅣ]로, 조사 ‘의’는 [ㅔ]로 발음함도 허용한다. 주의[주의/주이], 협의[혀븨/혀비], 우리의[우리의/우리에], 강의의[강ː의의/강ː이에]','slot:NUCLEUS,phoneme:ㅑ,phoneme:ㅒ,phoneme:ㅕ,phoneme:ㅖ,phoneme:ㅘ,phoneme:ㅙ,phoneme:ㅛ,phoneme:ㅝ,phoneme:ㅞ,phoneme:ㅠ,phoneme:ㅢ');
INSERT IGNORE INTO `knowledge_chunks` (`chunk_id`, `document_id`, `chunk_order`, `location`, `content`, `tags`) VALUES ('nikl-pron-vowel-guide-01','nikl-pron-vowel-guide',1,'제2장 제4항 해설(단모음 분류표)','단모음의 분류는 크게 혀의 위치, 입술 모양에 따라 이루어진다. 이 중 혀의 위치는 다시 전후 위치와 높이로 구별하기 때문에 실제로는 세 가지 기준에 따라 분류된다. 혀의 전후 위치에 따라 전설 모음과 후설 모음이, 혀의 높이에 따라 고모음, 중모음, 저모음이, 입술 모양에 따라 원순 모음과 평순 모음이 구분된다. [분류표] ㅣ: 전설 모음, 평순 모음, 고모음','phoneme:ㅣ');
