-- =============================================================================
-- 채터랜드 GCP Cloud SQL (MySQL 8.0 이상) 초기화 스크립트 — 자동 생성 파일, 직접 고치지 않는다.
-- 다시 만들기: MYSQL_USER=<계정> MYSQL_PWD=<비밀번호> sh backend/scripts/gcp/build_cloudsql.sh
--
-- 내용: 데이터베이스 chatterland + 테이블 26개 + 기본 데이터
--       센터 3, 연습 영역 5, 활성 연습 콘텐츠 1589개(articulation 355 / vocabulary 361 / fluency 311 / expression 302 / comprehension 260) · 문항 4182개,
--       AI 설명 근거 자료 문서 8 · 조각 48.
--       사용자 계정·학습 기록·숙제·비밀번호·키는 들어 있지 않다.
-- 출처: backend/src/main/resources/schema.sql + data.sql 을 빈 DB에 적용한 최종 상태(백엔드와 같은 스키마).
--
-- 기존 데이터를 지우지 않는다: DROP 문이 없고 CREATE TABLE IF NOT EXISTS · INSERT IGNORE 만 쓴다.
-- 같은 ID의 기존 행은 덮어쓰지 않으며, 여러 번 실행해도 중복이 생기지 않는다.
-- 이전 버전 스키마로 이미 만든 DB에는 새 테이블(homework_exercises, notification_settings 등)만 추가되고
-- 기존 테이블의 새 컬럼은 추가되지 않는다. 그 경우 백엔드를 한 번 시작하면 schema.sql 이 컬럼을 맞춘다.
--
-- 가져오기 (예: 인스턴스 chatterland-db, 버킷 my-bucket)
--   gsutil cp chatterland_cloudsql.sql gs://my-bucket/
--   gcloud sql import sql chatterland-db gs://my-bucket/chatterland_cloudsql.sql
--   (파일 안에 CREATE DATABASE chatterland 가 있으므로 --database 는 지정하지 않아도 된다)
--
-- 애플리케이션 계정은 콘솔이나 gcloud 로 따로 만든다(비밀번호를 이 파일에 적지 않는다).
--   gcloud sql users create ctland --instance=chatterland-db --password=<비밀번호>
--   백엔드 환경변수: DB_URL=jdbc:mariadb://<호스트>:3306/chatterland?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Seoul
--                   DB_USERNAME / DB_PASSWORD
-- 맨 끝의 검증 쿼리는 결과만 보여 주며 데이터를 바꾸지 않는다.
-- =============================================================================

SET NAMES utf8mb4;
SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;
SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0;
CREATE DATABASE IF NOT EXISTS `chatterland` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `chatterland`;

-- ── 테이블 ──────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS `centers` (
  `center_id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `conversation_messages` (
  `message_id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `speaker` enum('STUDENT','ASSISTANT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `audio_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_deleted_at` datetime DEFAULT NULL,
  `feedback` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`message_id`),
  KEY `idx_message_conversation` (`conversation_id`,`created_at`),
  CONSTRAINT `fk_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `conversations` (`conversation_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `conversations` (
  `conversation_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_id` bigint NOT NULL,
  `topic` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACTIVE','CLOSED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `ended_at` datetime DEFAULT NULL,
  PRIMARY KEY (`conversation_id`),
  KEY `idx_conversation_student` (`student_id`,`updated_at` DESC),
  CONSTRAINT `fk_conversation_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `exercise_items` (
  `item_id` bigint NOT NULL AUTO_INCREMENT,
  `exercise_id` bigint NOT NULL,
  `text_value` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emoji` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `uq_items_exercise_order` (`exercise_id`,`sort_order`),
  KEY `idx_items_exercise` (`exercise_id`,`sort_order`),
  CONSTRAINT `fk_items_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `exercises` (
  `exercise_id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instruction` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `input_type` enum('mic','read','speak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mic',
  `target_phonemes` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `difficulty` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pronunciation_rule` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`exercise_id`),
  KEY `idx_exercise_category` (`category_id`,`active`,`sort_order`),
  KEY `idx_exercise_filters` (`active`,`pronunciation_rule`,`difficulty`,`content_type`),
  CONSTRAINT `fk_exercise_category` FOREIGN KEY (`category_id`) REFERENCES `practice_categories` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `guardian_link_codes` (
  `code_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `code_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `used_by` bigint DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`code_id`),
  UNIQUE KEY `uq_guardian_link_code_hash` (`code_hash`),
  KEY `idx_guardian_link_code_student` (`student_id`,`created_at`),
  CONSTRAINT `fk_guardian_link_code_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `guardian_link_failures` (
  `failure_id` bigint NOT NULL AUTO_INCREMENT,
  `guardian_id` bigint NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`failure_id`),
  KEY `idx_guardian_link_failure` (`guardian_id`,`created_at`),
  CONSTRAINT `fk_guardian_link_failure_user` FOREIGN KEY (`guardian_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `guardian_students` (
  `guardian_id` bigint NOT NULL,
  `student_id` bigint NOT NULL,
  `status` enum('ACTIVE','UNLINKED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `linked_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `unlinked_at` datetime DEFAULT NULL,
  `unlinked_by` enum('GUARDIAN','STUDENT') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`guardian_id`,`student_id`),
  KEY `idx_guardian_students_student` (`student_id`,`status`),
  CONSTRAINT `fk_guardian_students_guardian` FOREIGN KEY (`guardian_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_guardian_students_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `homework_exercises` (
  `homework_id` bigint NOT NULL,
  `exercise_id` bigint NOT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  PRIMARY KEY (`homework_id`,`exercise_id`),
  KEY `idx_homework_exercise_order` (`homework_id`,`sort_order`),
  KEY `fk_homework_exercises_exercise` (`exercise_id`),
  CONSTRAINT `fk_homework_exercises_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_homework_exercises_homework` FOREIGN KEY (`homework_id`) REFERENCES `homeworks` (`homework_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `homeworks` (
  `homework_id` bigint NOT NULL AUTO_INCREMENT,
  `teacher_id` bigint NOT NULL,
  `student_id` bigint NOT NULL,
  `title` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_minutes` smallint unsigned NOT NULL DEFAULT '10',
  `due_date` date NOT NULL,
  `status` enum('PENDING','IN_PROGRESS','COMPLETED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `version` int NOT NULL DEFAULT '0',
  `request_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `request_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `exercise_id` bigint DEFAULT NULL,
  PRIMARY KEY (`homework_id`),
  UNIQUE KEY `uq_homework_request_key` (`teacher_id`,`request_key`),
  KEY `idx_homework_teacher_due` (`teacher_id`,`due_date`),
  KEY `idx_homework_student` (`student_id`,`status`),
  KEY `fk_homework_exercise` (`exercise_id`),
  CONSTRAINT `fk_homework_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_homework_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`),
  CONSTRAINT `fk_homework_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `knowledge_chunks` (
  `chunk_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `document_id` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chunk_order` int NOT NULL,
  `location` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` varchar(2000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tags` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`chunk_id`),
  KEY `idx_chunk_document` (`document_id`,`chunk_order`),
  CONSTRAINT `fk_chunk_document` FOREIGN KEY (`document_id`) REFERENCES `knowledge_documents` (`document_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `knowledge_documents` (
  `document_id` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_citation` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publisher` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published_year` smallint DEFAULT NULL,
  `topic` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `license_note` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `review_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `version` int NOT NULL DEFAULT '1',
  `reviewed_by` bigint DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `category` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_version` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verification_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `verified_at` datetime DEFAULT NULL,
  `verification_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`document_id`),
  KEY `idx_knowledge_status` (`review_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `notification_settings` (
  `user_id` bigint NOT NULL,
  `homework_assigned` tinyint(1) NOT NULL DEFAULT '1',
  `homework_changed` tinyint(1) NOT NULL DEFAULT '1',
  `homework_due_soon` tinyint(1) NOT NULL DEFAULT '1',
  `homework_overdue` tinyint(1) NOT NULL DEFAULT '1',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `fk_notification_settings_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `password_change_failures` (
  `failure_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`failure_id`),
  KEY `idx_pw_change_failure_user` (`user_id`,`created_at`),
  CONSTRAINT `fk_pw_change_failure_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `password_reset_requests` (
  `request_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `code_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_expires_at` datetime NOT NULL,
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `verified_at` datetime DEFAULT NULL,
  `invalidated_at` datetime DEFAULT NULL,
  `reset_token_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reset_token_expires_at` datetime DEFAULT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`request_id`),
  UNIQUE KEY `uq_reset_token` (`reset_token_hash`),
  KEY `idx_reset_user_created` (`user_id`,`created_at`),
  CONSTRAINT `fk_reset_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `practice_attempts` (
  `attempt_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `exercise_id` bigint NOT NULL,
  `item_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `analysis_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `score` decimal(5,2) DEFAULT NULL,
  `match_rate` decimal(5,2) DEFAULT NULL,
  `attempt_type` enum('PRACTICE','HOMEWORK','AI_CHAT','SELF','LESSON') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRACTICE',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `homework_id` bigint DEFAULT NULL,
  PRIMARY KEY (`attempt_id`),
  UNIQUE KEY `uq_attempt_analysis` (`analysis_id`),
  KEY `idx_attempt_student_date` (`student_id`,`created_at` DESC),
  KEY `fk_attempt_exercise` (`exercise_id`),
  KEY `fk_attempt_homework` (`homework_id`),
  CONSTRAINT `fk_attempt_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `speech_analyses` (`analysis_id`),
  CONSTRAINT `fk_attempt_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_attempt_homework` FOREIGN KEY (`homework_id`) REFERENCES `homeworks` (`homework_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_attempt_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `practice_categories` (
  `category_id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `sort_order` smallint NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `refresh_tokens` (
  `token_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `session_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`token_id`),
  UNIQUE KEY `uq_refresh_hash` (`token_hash`),
  KEY `idx_refresh_user` (`user_id`),
  KEY `idx_refresh_session` (`session_id`),
  KEY `idx_refresh_expires` (`expires_at`),
  KEY `idx_refresh_revoked` (`revoked_at`),
  CONSTRAINT `fk_refresh_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `session_exercises` (
  `session_id` bigint NOT NULL,
  `exercise_id` bigint NOT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  PRIMARY KEY (`session_id`,`exercise_id`),
  KEY `fk_session_exercise_exercise` (`exercise_id`),
  CONSTRAINT `fk_session_exercise_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_session_exercise_session` FOREIGN KEY (`session_id`) REFERENCES `therapy_sessions` (`session_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `speech_ai_feedback` (
  `analysis_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `feedback_text` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prompt_version` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `sources_json` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`analysis_id`),
  CONSTRAINT `fk_ai_feedback_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `speech_analyses` (`analysis_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `speech_analyses` (
  `analysis_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_id` bigint NOT NULL,
  `exercise_id` bigint NOT NULL,
  `item_id` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `audio_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_mime` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PENDING','PROCESSING','COMPLETED','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `pronunciation_score` decimal(5,2) DEFAULT NULL,
  `speech_rate_score` decimal(5,2) DEFAULT NULL,
  `fluency_score` decimal(5,2) DEFAULT NULL,
  `overall_score` decimal(5,2) DEFAULT NULL,
  `transcript` text COLLATE utf8mb4_unicode_ci,
  `feedback` text COLLATE utf8mb4_unicode_ci,
  `error_code` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evaluation_mode` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_rate` decimal(5,2) DEFAULT NULL,
  `comparison_json` text COLLATE utf8mb4_unicode_ci,
  `recognition_confidence` decimal(5,4) DEFAULT NULL,
  `engine_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model_name` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `analysis_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assessment_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assessment_json` text COLLATE utf8mb4_unicode_ci,
  `analysis_version` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `request_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `request_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pronunciation_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `teacher_judgement` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `teacher_note` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `teacher_confirmed_json` text COLLATE utf8mb4_unicode_ci,
  `reviewed_by` bigint DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `audio_deleted_at` datetime DEFAULT NULL,
  `audio_expires_at` datetime DEFAULT NULL,
  `audio_delete_attempts` smallint NOT NULL DEFAULT '0',
  `audio_delete_error` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`analysis_id`),
  UNIQUE KEY `uq_analysis_request_key` (`student_id`,`request_key`),
  KEY `idx_analysis_student` (`student_id`,`created_at` DESC),
  KEY `fk_analysis_exercise` (`exercise_id`),
  CONSTRAINT `fk_analysis_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercises` (`exercise_id`),
  CONSTRAINT `fk_analysis_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `student_profiles` (
  `student_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `center_id` bigint NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `age` tinyint unsigned DEFAULT NULL,
  `sessions_limit` smallint unsigned NOT NULL DEFAULT '20',
  `parent_phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `focus_areas` varchar(600) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('ACTIVE','PAUSED','COMPLETED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `learner_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL',
  `memo` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`student_id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `idx_student_profile_center` (`center_id`,`status`,`name`),
  CONSTRAINT `fk_student_profile_center` FOREIGN KEY (`center_id`) REFERENCES `centers` (`center_id`),
  CONSTRAINT `fk_student_profile_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `teacher_students` (
  `teacher_id` bigint NOT NULL,
  `student_id` bigint NOT NULL,
  `status` enum('ACTIVE','INACTIVE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `memo` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`teacher_id`,`student_id`),
  KEY `fk_teacher_students_student` (`student_id`),
  CONSTRAINT `fk_teacher_students_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`),
  CONSTRAINT `fk_teacher_students_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `therapy_sessions` (
  `session_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `title` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scheduled_at` datetime DEFAULT NULL,
  `status` enum('UPCOMING','IN_PROGRESS','COMPLETED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPCOMING',
  `summary` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`session_id`),
  KEY `idx_session_student_date` (`student_id`,`scheduled_at` DESC),
  CONSTRAINT `fk_session_student` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `user_consents` (
  `consent_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `consent_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agreed` tinyint(1) NOT NULL,
  `policy_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agreed_at` datetime DEFAULT NULL,
  `withdrawn_at` datetime DEFAULT NULL,
  `guardian_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guardian_relation` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`consent_id`),
  UNIQUE KEY `uq_user_consent` (`user_id`,`consent_type`),
  CONSTRAINT `fk_consent_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `users` (
  `user_id` bigint NOT NULL AUTO_INCREMENT,
  `role` enum('STUDENT','TEACHER','GUARDIAN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `center_id` bigint NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `age` tinyint unsigned DEFAULT NULL,
  `terms_agreed` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('ACTIVE','INACTIVE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `token_version` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_users_email` (`email`),
  KEY `idx_users_center_role` (`center_id`,`role`),
  CONSTRAINT `fk_users_center` FOREIGN KEY (`center_id`) REFERENCES `centers` (`center_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



